Animal[] zoo = [new Dog("Rex"), new Cat("Tom"), new Animal("Generic")];

foreach (Animal animal in zoo)
{
    Console.WriteLine($"{animal.Name}: {animal.Speak()}");
}

class Animal(string name)
{
    public string Name { get; } = name;

    public virtual string Speak() => "...";
}

class Dog(string name) : Animal(name)
{
    public override string Speak() => "Woof";
}

class Cat(string name) : Animal(name)
{
    public override string Speak() => "Meow";
}

Shape[] shapes = [new Circle(1), new Rectangle(2, 3)];

foreach (Shape shape in shapes)
{
    Console.WriteLine(shape.Describe());
}

abstract class Shape
{
    public abstract double Area();

    public string Describe() => $"{GetType().Name} with area {Area():F2}";
}

class Circle(double radius) : Shape
{
    public override double Area() => Math.PI * radius * radius;
}

class Rectangle(double width, double height) : Shape
{
    public override double Area() => width * height;
}

INotifier[] channels = [new EmailNotifier(), new SmsNotifier("+44 7700 900123")];

foreach (INotifier channel in channels)
{
    channel.Send("Build finished");
}

interface INotifier
{
    void Send(string message);
}

class EmailNotifier : INotifier
{
    public void Send(string message) => Console.WriteLine($"Email: {message}");
}

class SmsNotifier(string number) : INotifier
{
    public void Send(string message) => Console.WriteLine($"SMS to {number}: {message}");
}

Player[] players = [new Player("Ada", 1500), new Player("Linus", 1800), new Player("Grace", 1650)];

Array.Sort(players);
foreach (Player player in players)
{
    Console.WriteLine($"{player.Name} {player.Rating}");
}

class Player(string name, int rating) : IComparable<Player>
{
    public string Name { get; } = name;
    public int Rating { get; } = rating;

    public int CompareTo(Player? other) =>
        other is null ? 1 : other.Rating.CompareTo(Rating);   // highest rating first
}

object[] items = [42, "hello", new int[] { 1, 2 }, 3.5];

foreach (object item in items)
{
    if (item is int number)
        Console.WriteLine($"int {number}");
    else if (item is string text)
        Console.WriteLine($"string of length {text.Length}");
    else if (item is int[] array)
        Console.WriteLine($"array of {array.Length}");
    else
        Console.WriteLine($"something else: {item}");
}
